【R7 可运行的参考写法】已在本机 %TEMP% 副本实测：未改实现时 45/45 全绿（exit 0）；对 wiring-straight-render 变异体 exit 1。

```js
// 防假绿三原则：① 同一谓词+同一输入，两侧都真跑；② 必须 pristine===true 且 mutant===false
//（恒真谓词在 mutant 侧失败、恒假谓词在 pristine 侧失败，都不可能假绿）；
// ③ 变异锚点命中数必须恰为 1，否则 check() 判 FAIL（重构时喊出来，不静默通过）。
function apiFromBody(srcBody) {
  const a = new Function('document', 'window', 'fetch',
    'return (function(){' + srcBody + '\n; return { renderMap: renderMap, setField: function(f){ FIELD = f; },'
    + ' cellCenter: cellCenter, routePolyline: routePolyline, carHeadVec: headVec }; })();'
  )({ getElementById: el, querySelectorAll() { return [] }, addEventListener() {} }, windowStub, fetchStub)
  a.setField(field)                    // ★ 必须，否则 FIELD 为 null，cellCenter 会抛错
  return a
}
function mutantOf(label, find, repl) {
  const hits = body.split(find).length - 1
  if (hits !== 1) return null          // 锚点失配 ⇒ 由下面的 check 判 FAIL，而不是静默通过
  return apiFromBody(body.replace(find, repl))
}
// ① 函数级退化（对应 R1/A 组）
const PRED_POLY = a => JSON.stringify(a.routePolyline(['A1','D1'])) === JSON.stringify([[17,17],[51,17],[85,17],[119,17]])
const mPoly = mutantOf('折线→首末两点', 'function routePolyline(cells) {\n  var out = [];\n',
  'function routePolyline(cells) {\n  var out = [];\n  var __c = cells.map(cellCenter).filter(Boolean);\n  if (__c.length) return [__c[0], __c[__c.length - 1]];\n')
check('变异自证 A：折线退化 ⇒ A1→D1 谓词由真变假',
  mPoly !== null && PRED_POLY(api) === true && PRED_POLY(mPoly) === false, 'mutant=' + (mPoly !== null))

// ② 接线级退化（补 R4 那条缺口）——必须用跨格合成路线；真实路线 54 token 全逐格，区分不出来
const polyPts = a => { a.setField(Object.assign({}, field, { route: ['A1','C1','C4'] })); a.renderMap()
  const m = el('map').innerHTML.match(/<polyline[^>]*points="([^"]*)"/)
  return m ? m[1].trim().split(/\s+/).length : 0 }
const mWire = mutantOf('renderMap 绕过 routePolyline', '    var pts = routePolyline(cells);',
  '    var pts = cells.map(cellCenter).filter(Boolean);')
check('变异自证 A-wiring：renderMap 绕过 routePolyline ⇒ 跨格折线点数由 6 降为 3',
  mWire !== null && polyPts(api) === 6 && polyPts(mWire) === 3, 'pristine=' + polyPts(api))
api.setField(field); api.renderMap()   // 复原 FIELD

// ③ 朝向类退化（补 R3 那条缺口）
const PRED_HEAD = a => a.carHeadVec(0)[1] < 0
const mHead = mutantOf('车头镜像', 'return [Math.cos(th), -Math.sin(th)];', 'return [Math.cos(th), Math.sin(th)];')
check('变异自证 B-heading：车头 y 轴镜像 ⇒ 朝向谓词由真变假',
  mHead !== null && PRED_HEAD(apiFromBody(body)) === true && PRED_HEAD(mHead) === false, '')
```

两点落地注意：(a) 锚点失配我实测是直接 throw（exit 1，也算抓住但归因难看），正式落地建议按上面 `mutantOf` 返回 null + check 判 FAIL，让失败以「断言失败」呈现；(b) 该手法仍不能覆盖 renderMap 调用点的退化（所以 ② 是专门为它写的），因此 R7 措辞只应把「接线级需外部/内存替换」保留为外部验证的必要性理由。

